package findu.backend.notification.entity;import findu.backend.global.entity.BaseEntity;import findu.backend.user.entity.User;import jakarta.persistence.*;import lombok.*;@Entity @Getter @Builder @NoArgsConstructor(access=AccessLevel.PROTECTED)@AllArgsConstructor @Table(name="notifications")public class Notification extends BaseEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")User user;@Column(nullable=false,length=30)String type;@Column(nullable=false,length=500)String message;@Builder.Default @Column(nullable=false)boolean read=false;public void markRead(){read=true;}}
